// resolveApiBase: --api-base flag > PIEZAS_API_BASE env > fallback (the
// default recorded in piezas.manifest.json's apiBaseUrl).
export function resolveApiBase(options, env, fallback = DEFAULT_API_BASE_URL) {
  const flagBase = typeof options.apiBase === 'string' && options.apiBase.trim()
    ? options.apiBase.trim()
    : undefined;
  const envBase = typeof env.PIEZAS_API_BASE === 'string' && env.PIEZAS_API_BASE.trim()
    ? env.PIEZAS_API_BASE.trim()
    : undefined;
  return (flagBase || envBase || fallback).replace(/\/+$/, '');
}

export function adminBaseUrl(apiBase) {
  return `${apiBase}${ADMIN_PATH_PREFIX}`;
}

// credentialsFilePath honors PIEZAS_HOME (used by tests) and defaults to
// ~/.piezas/credentials.json.
export function credentialsFilePath(env = process.env) {
  const home = typeof env.PIEZAS_HOME === 'string' && env.PIEZAS_HOME.trim()
    ? env.PIEZAS_HOME.trim()
    : join(homedir(), '.piezas');
  return join(home, 'credentials.json');
}

// readCredentials returns the stored CLI session or undefined. Corrupt or
// token-less files read as "logged out" — never throw.
export function readCredentials(env = process.env) {
  const filePath = credentialsFilePath(env);
  if (!existsSync(filePath)) return undefined;
  try {
    const parsed = JSON.parse(readFileSync(filePath, 'utf-8'));
    if (!parsed || typeof parsed !== 'object' || typeof parsed.cliToken !== 'string' || !parsed.cliToken) {
      return undefined;
    }
    return parsed;
  } catch {
    return undefined;
  }
}

export function writeCredentials(credentials, env = process.env) {
  const filePath = credentialsFilePath(env);
  mkdirSync(dirname(filePath), { recursive: true, mode: 0o700 });
  writeFileSync(filePath, `${JSON.stringify(credentials, null, 2)}\n`, { mode: 0o600 });
  // writeFileSync's mode only applies on create — enforce on rewrite too.
  chmodSync(filePath, 0o600);
  return filePath;
}

// fetchJson: built-in fetch with a hard timeout and JSON parse guards.
// Non-2xx statuses are returned (not thrown); network errors/timeouts throw.
// form sends a form-encoded body instead, as the OAuth endpoints require.
export async function fetchJson(fetchFn, url, { method = 'GET', body, form, token, timeoutMs = HTTP_TIMEOUT_MS } = {}) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    const headers = { accept: 'application/json' };
    let payload;
    if (form !== undefined) {
      headers['content-type'] = 'application/x-www-form-urlencoded';
      payload = new URLSearchParams(form).toString();
    } else if (body !== undefined) {
      headers['content-type'] = 'application/json';
      payload = JSON.stringify(body);
    }
    if (token) headers.authorization = `Bearer ${token}`;
    const response = await netFetch(fetchFn, url, {
      method,
      headers,
      body: payload,
      signal: controller.signal,
    });
    let data;
    try {
      data = await response.json();
    } catch {
      data = undefined;
    }
    return { status: response.status, data };
  } finally {
    clearTimeout(timer);
  }
}

// openInBrowser best-effort opens a URL. Failures are swallowed — the URL is
// always printed, so the user can click/copy it manually.
export function openInBrowser(url) {
  try {
    const [command, args] = process.platform === 'darwin'
      ? ['open', [url]]
      : process.platform === 'win32'
        ? ['cmd', ['/c', 'start', '', url]]
        : ['xdg-open', [url]];
    const child = spawn(command, args, { stdio: 'ignore', detached: true });
    child.on('error', () => {});
    child.unref();
    return true;
  } catch {
    return false;
  }
}

export function printUserCode(userCode) {
  const inner = `   ${userCode}   `;
  const line = '─'.repeat(inner.length);
  log(`      ╭${line}╮`);
  log(`      │${inner}│`);
  log(`      ╰${line}╯`);
}

export const LOGIN_RETRY_HINT = 'Run `npx piezas login` to get a new code.';

// The CLI is admin-api's `piezas-cli` public client (RFC 8628 device grant).
export const CLI_CLIENT_ID = 'piezas-cli';
export const DEVICE_CODE_GRANT = 'urn:ietf:params:oauth:grant-type:device_code';
// RFC 8628 §3.5: every slow_down adds 5 seconds to the polling interval.
export const SLOW_DOWN_STEP_MS = 5000;

// A device flow starts a sign-in and polls it. start() resolves to
// { status, device }, device set only on success. poll() resolves to { state }:
// 'ok' (with credentials), 'pending', 'slow_down', 'gone' or 'failed' (with
// the HTTP status).

// oauthDeviceFlow speaks RFC 8628 to admin-api's OAuth server.
export function oauthDeviceFlow(fetchFn, admin, timeoutMs) {
  return {
    async start() {
      const res = await fetchJson(fetchFn, `${admin}/oauth/device_authorization`, {
        method: 'POST',
        form: { client_id: CLI_CLIENT_ID },
        timeoutMs,
      });
      const data = res.status === 200 ? res.data : undefined;
      return {
        status: res.status,
        device: data && {
          deviceCode: data.device_code,
          userCode: data.user_code,
          verificationUri: data.verification_uri,
          interval: data.interval,
          expiresIn: data.expires_in,
        },
      };
    },
    async poll(deviceCode) {
      const res = await fetchJson(fetchFn, `${admin}/oauth/token`, {
        method: 'POST',
        form: { grant_type: DEVICE_CODE_GRANT, device_code: deviceCode, client_id: CLI_CLIENT_ID },
        timeoutMs,
      });
      if (res.status === 200 && typeof res.data?.access_token === 'string') {
        return {
          state: 'ok',
          credentials: {
            cliToken: res.data.access_token,
            tenantId: res.data.tenant_id,
            tenantName: res.data.tenant_name,
            email: res.data.email,
          },
        };
      }
      if (res.status === 429 || res.status >= 500) return { state: 'pending' }; // transient
      // A 401/403 (e.g. invalid_client) cannot succeed on a later poll.
      if (res.status !== 400) return { state: 'failed', status: res.status };
      if (res.data?.error === 'authorization_pending') return { state: 'pending' };
      if (res.data?.error === 'slow_down') return { state: 'slow_down' };
      return { state: 'gone' }; // expired_token, invalid_grant, access_denied, ...
    },
  };
}

// legacyDeviceFlow is admin-api's /v1/portal/device-codes API, for a server
// without /oauth/device_authorization. Remove it with those routes.
export function legacyDeviceFlow(fetchFn, admin, timeoutMs) {
  return {
    async start() {
      const res = await fetchJson(fetchFn, `${admin}/v1/portal/device-codes`, { method: 'POST', timeoutMs });
      return { status: res.status, device: res.status === 201 ? res.data : undefined };
    },
    async poll(deviceCode) {
      const res = await fetchJson(fetchFn, `${admin}/v1/portal/device-codes/token`, {
        method: 'POST',
        body: { deviceCode },
        timeoutMs,
      });
      if (res.status === 200 && res.data?.status === 'ok' && typeof res.data.cliToken === 'string') {
        return {
          state: 'ok',
          credentials: {
            cliToken: res.data.cliToken,
            tenantId: res.data.tenantId,
            tenantName: res.data.tenantName,
            email: res.data.email,
          },
        };
      }
      if (res.status === 200) return { state: 'pending' };
      if (res.status === 404 || res.status === 400) return { state: 'gone' };
      return { state: 'pending' }; // transient
    },
  };
}

// offerBrowserOpen offers "hit ENTER to open the browser" WITHOUT blocking the
// approval poll: polling runs concurrently, so approving via the pasted link
// completes login even if ENTER is never pressed. Returns cancel() to detach the
// listener once polling ends, so the process exits cleanly instead of hanging on
// stdin.
export function offerBrowserOpen(options, url, opener) {
  const promptText =
    '  Press ENTER to open your browser (or open the link above yourself)... ';
  let done = false;
  const openNow = () => {
    if (done) return;
    done = true;
    if (opener(url)) {
      log('  Opening your browser... (if nothing happens, use the link above)');
    }
  };
  if (options.promptFn) {
    // Injected/non-terminal caller: resolve the prompt → open. Nothing to detach.
    Promise.resolve(options.promptFn(promptText)).then(openNow).catch(() => {});
    return () => { done = true; };
  }
  // Real terminal: a one-shot stdin line. Opening is optional and non-blocking —
  // the poll is what actually completes login.
  log(promptText.trimEnd());
  const stdin = process.stdin;
  const detach = () => {
    stdin.removeListener('data', onData);
    stdin.pause();
  };
  const onData = () => { detach(); openNow(); };
  stdin.resume();
  stdin.on('data', onData);
  return () => { if (!done) { done = true; detach(); } };
}

export async function login(options = {}) {
  const previousEmit = io.emit;
  if (options.json) {
    io.emit = (message) => process.stderr.write(`${message}\n`);
  }
  let outcome;
  try {
    outcome = await runLogin(options);
  } finally {
    io.emit = previousEmit;
  }
  if (options.json) {
    console.log(JSON.stringify(outcome.summary, null, 2));
  }
  return { exitCode: outcome.exitCode, ...outcome.summary };
}

// beginSignIn asks Piezas for a device code (the OAuth device grant, falling
// back to the older device-code route on a server without it). Returns
// { ok: true, flowKind, flow, device, confirmUrl, apiBase } or
// { ok: false, outcome } with the plain-language failure already logged.
export async function beginSignIn(options) {
  const env = options.env ?? process.env;
  const fetchFn = options.fetchFn ?? fetch;
  // --staging / --production choose which Piezas to sign in to, and the choice
  // is saved with the sign-in so every later command follows it.
  const hosts = options.target ? TARGET_HOSTS[options.target] : TARGET_HOSTS[savedTarget(env)] ?? TARGET;
  const apiBase = resolveApiBase(options, env, hosts.api);
  const admin = adminBaseUrl(apiBase);

  let flowKind = 'oauth';
  let flow = oauthDeviceFlow(fetchFn, admin, options.httpTimeoutMs);
  let start;
  try {
    start = await flow.start();
    // Only a missing route falls back; any other refusal is reported as is.
    if (start.status === 404) {
      flowKind = 'legacy';
      flow = legacyDeviceFlow(fetchFn, admin, options.httpTimeoutMs);
      start = await flow.start();
    }
  } catch (error) {
    log(`  Could not reach ${apiBase} (${error?.message || 'network error'}). Check your connection and try again.`);
    return { ok: false, outcome: { exitCode: 1, summary: { command: 'login', status: 'error', error: 'unreachable', apiBase } } };
  }

  if (start.status === 429) {
    log('  Too many sign-in requests are pending right now - wait a few minutes and try again.');
    return { ok: false, outcome: { exitCode: 1, summary: { command: 'login', status: 'error', error: 'rate-limited', apiBase } } };
  }
  const { device } = start;
  if (!device || typeof device.deviceCode !== 'string' || typeof device.userCode !== 'string') {
    log(`  Sign-in could not be started (HTTP ${start.status}). Try again in a moment.`);
    return { ok: false, outcome: { exitCode: 1, summary: { command: 'login', status: 'error', error: `http-${start.status}`, apiBase } } };
  }

  const verificationUri = device.verificationUri || `${hosts.console}/device`;
  const confirmUrl = `${verificationUri}${verificationUri.includes('?') ? '&' : '?'}code=${encodeURIComponent(device.userCode)}`;
  return { ok: true, flowKind, flow, device, confirmUrl, apiBase };
}

// pollSignIn polls until the code is approved, expires or is refused, then
// saves the sign-in (and the --staging/--production choice). deadline is a
// timestamp in milliseconds.
export async function pollSignIn({ flow, device, apiBase, target, deadline, codeExpiresAt }, options) {
  const env = options.env ?? process.env;
  let intervalMs = options.pollIntervalMs
    ?? (Number(device.interval) > 0 ? Number(device.interval) : 5) * 1000;
  const slowDownMs = options.slowDownMs ?? SLOW_DOWN_STEP_MS;

  while (Date.now() < deadline) {
    await new Promise((resolveDelay) => setTimeout(resolveDelay, intervalMs));
    let poll;
    try {
      poll = await flow.poll(device.deviceCode);
    } catch {
      continue; // transient network trouble — keep polling until expiry
    }

    if (poll.state === 'ok') {
      const credentials = { ...poll.credentials, apiBase };
      const credentialsPath = writeCredentials(credentials, env);
      if (target) saveTarget(target, env);
      log('');
      log(`  Logged in as ${credentials.email}${credentials.tenantName ? ` (${credentials.tenantName})` : ''}.`);
      log(`  Session saved to ${credentialsPath}`);
      log('  Next: run `npx piezas init` in your project folder.\n');
      return {
        exitCode: 0,
        summary: {
          command: 'login',
          status: 'ok',
          tenantId: credentials.tenantId ?? null,
          tenantName: credentials.tenantName ?? null,
          email: credentials.email ?? null,
          apiBase,
          credentialsPath,
        },
      };
    }
    if (poll.state === 'failed') {
      log(`  Sign-in failed (HTTP ${poll.status}). ${LOGIN_RETRY_HINT}`);
      return { exitCode: 1, summary: { command: 'login', status: 'error', error: `http-${poll.status}`, apiBase } };
    }
    if (poll.state === 'slow_down') {
      intervalMs += slowDownMs;
      continue;
    }
    if (poll.state === 'gone') {
      log(`  This sign-in code is no longer valid (expired or already used). ${LOGIN_RETRY_HINT}`);
      return { exitCode: 1, summary: { command: 'login', status: 'expired', apiBase } };
    }
    // Pending, including a transient 429/5xx — keep polling until expiry.
  }

  if (codeExpiresAt !== undefined && Date.now() < codeExpiresAt) {
    log('  Not approved yet. The code is still valid: run `piezas login --wait` again.');
    return { exitCode: 1, summary: { command: 'login', status: 'waiting', apiBase } };
  }
  log(`  The sign-in code expired before it was approved. ${LOGIN_RETRY_HINT}`);
  return { exitCode: 1, summary: { command: 'login', status: 'expired', apiBase } };
}

export async function runLogin(options) {
  log(`\n  🧱 Piezas login${options.target === 'staging' ? ' (staging)' : ''}\n`);
  const begun = await beginSignIn(options);
  if (!begun.ok) return begun.outcome;
  const { flow, device, confirmUrl, apiBase } = begun;

  log('  Confirm this code in your browser to sign in:');
  log('');
  printUserCode(device.userCode);
  log('');
  log(`  ${confirmUrl}`);
  log('');
  const opener = options.openBrowserFn ?? openInBrowser;
  // --open (and any run by an AI tool, where nobody can press ENTER) opens the
  // browser straight away; the code and link above stay printed either way.
  if (options.open) {
    opener(confirmUrl);
    log('  Your browser is opening. Check the code matches, then click Approve.');
    log('');
  }
  // Offer to open the browser (npm/gh style — never auto-hijack). Interactive when
  // the caller says so (main() passes it based on a real TTY) or provides a
  // promptFn; --json and interactive:false stay hands-off and just print the link.
  const wantsPrompt =
    !options.open &&
    options.interactive !== false &&
    !options.json &&
    (options.interactive === true ||
      (options.promptFn !== undefined && options.promptFn !== null));
  // CRITICAL: the offer must NOT block the poll below. Approving via the pasted
  // link has to complete login even if ENTER is never pressed, so the "hit ENTER
  // to open" offer runs concurrently and is cancelled once polling ends.
  const cancelOffer = wantsPrompt
    ? offerBrowserOpen(options, confirmUrl, opener)
    : () => {};
  log('  Waiting for approval...');

  const lifetimeMs = (Number(device.expiresIn) > 0 ? Number(device.expiresIn) : 900) * 1000;
  try {
    return await pollSignIn({ flow, device, apiBase, target: options.target, deadline: Date.now() + lifetimeMs }, options);
  } finally {
    cancelOffer();
  }
}

// --- Two-step sign-in, for AI tools -------------------------------------------
// An AI tool can only pass on a command's output once the command ends, and a
// sandbox may not be able to open a browser. So `login --start` prints the
// approval link and exits at once (the tool shows it as a clickable link), and
// `login --wait` then waits for the approval. The pending code is saved, owner
// readable only, between the two.

// The longest `login --wait` waits in one run.
export const LOGIN_WAIT_MAX_MS = 10 * 60 * 1000;

export function pendingLoginPath(env = process.env) {
  return join(piezasHomeDir(env), 'pending-login.json');
}

function readPendingLogin(env) {
  try {
    const parsed = JSON.parse(readFileSync(pendingLoginPath(env), 'utf-8'));
    return parsed && typeof parsed.deviceCode === 'string' ? parsed : undefined;
  } catch {
    return undefined;
  }
}

function clearPendingLogin(env) {
  try { unlinkSync(pendingLoginPath(env)); } catch { /* already gone */ }
}

export async function loginStart(options = {}) {
  const env = options.env ?? process.env;
  const begun = await beginSignIn(options);
  if (!begun.ok) {
    if (options.json) console.log(JSON.stringify(begun.outcome.summary, null, 2));
    return { exitCode: begun.outcome.exitCode, ...begun.outcome.summary };
  }
  const { flowKind, device, confirmUrl, apiBase } = begun;
  const expiresIn = Number(device.expiresIn) > 0 ? Number(device.expiresIn) : 900;
  const file = pendingLoginPath(env);
  mkdirSync(dirname(file), { recursive: true, mode: 0o700 });
  writeFileSync(file, `${JSON.stringify({
    deviceCode: device.deviceCode,
    userCode: device.userCode,
    interval: Number(device.interval) > 0 ? Number(device.interval) : 5,
    expiresAt: Date.now() + expiresIn * 1000,
    flowKind,
    apiBase,
    target: options.target ?? null,
    url: confirmUrl,
  }, null, 2)}\n`, { mode: 0o600 });
  chmodSync(file, 0o600);

  const opener = options.openBrowserFn ?? openInBrowser;
  if (options.open !== false) opener(confirmUrl);

  const summary = { command: 'login', status: 'started', url: confirmUrl, code: device.userCode, expiresIn, apiBase };
  if (options.json) {
    console.log(JSON.stringify(summary, null, 2));
  } else {
    console.log(`  Open this link to sign in to Piezas: ${confirmUrl}  (code ${device.userCode})`);
    console.log('  Then run `piezas login --wait`.');
  }
  return { exitCode: 0, ...summary };
}

export async function loginWait(options = {}) {
  const env = options.env ?? process.env;
  const pending = readPendingLogin(env);
  const fail = (status, message) => {
    log(`  ${message}`);
    const summary = { command: 'login', status };
    if (options.json) console.log(JSON.stringify(summary, null, 2));
    return { exitCode: 1, ...summary };
  };
  if (!pending) return fail('no-pending', 'No sign-in is waiting. Run `piezas login --start` first.');
  if (Date.now() >= pending.expiresAt) {
    clearPendingLogin(env);
    return fail('expired', 'That sign-in code has expired. Run `piezas login --start` for a new one.');
  }

  const fetchFn = options.fetchFn ?? fetch;
  const admin = adminBaseUrl(pending.apiBase);
  const flow = pending.flowKind === 'legacy'
    ? legacyDeviceFlow(fetchFn, admin, options.httpTimeoutMs)
    : oauthDeviceFlow(fetchFn, admin, options.httpTimeoutMs);
  log(`  Waiting for you to approve code ${pending.userCode}...`);
  const maxWaitMs = options.maxWaitMs ?? LOGIN_WAIT_MAX_MS;
  const deadline = Math.min(pending.expiresAt, Date.now() + maxWaitMs);

  const previousEmit = io.emit;
  if (options.json) io.emit = (message) => process.stderr.write(`${message}\n`);
  let outcome;
  try {
    outcome = await pollSignIn({
      flow,
      device: { deviceCode: pending.deviceCode, interval: pending.interval },
      apiBase: pending.apiBase,
      target: pending.target ?? undefined,
      deadline,
      codeExpiresAt: pending.expiresAt,
    }, options);
  } finally {
    io.emit = previousEmit;
  }
  // Keep the code only while it can still be approved; a later --wait resumes it.
  if (outcome.summary.status !== 'waiting') clearPendingLogin(env);
  if (options.json) console.log(JSON.stringify(outcome.summary, null, 2));
  return { exitCode: outcome.exitCode, ...outcome.summary };
}

// How long logout waits for the server-side session revocation before giving
// up and deleting the local credentials anyway.
export const LOGOUT_REVOKE_TIMEOUT_MS = 2000;

export async function logout(options = {}) {
  const env = options.env ?? process.env;
  const credentialsPath = credentialsFilePath(env);
  const credentials = readCredentials(env);

  // Best-effort server-side revocation BEFORE deleting the local file: the
  // 30-day cliToken is bound to a revocable server session, so logging out
  // kills any copy of the token, not just this machine's file. Failures
  // (offline, expired, 5xx, hung server) never block the local logout.
  let revoked = false;
  if (credentials?.cliToken) {
    const fetchFn = options.fetchFn ?? fetch;
    const apiBase = resolveApiBase(options, env, credentials.apiBase || DEFAULT_API_BASE_URL);
    try {
      const response = await fetchJson(fetchFn, `${adminBaseUrl(apiBase)}/v1/portal/cli-sessions/revoke`, {
        method: 'POST',
        token: credentials.cliToken,
        timeoutMs: options.revokeTimeoutMs ?? LOGOUT_REVOKE_TIMEOUT_MS,
      });
      revoked = response.status === 200;
    } catch {
      // ignore — logout is local-first
    }
  }

  let removed = false;
  if (existsSync(credentialsPath)) {
    unlinkSync(credentialsPath);
    removed = true;
  }
  const summary = { command: 'logout', removed, revoked, credentialsPath };
  if (options.json) {
    console.log(JSON.stringify(summary, null, 2));
  } else {
    console.log(removed ? '  Logged out of Piezas.' : '  Not logged in - nothing to remove.');
  }
  return { exitCode: 0, ...summary };
}

// signInStatus: is this computer signed in to the Piezas this setup talks to?
// A session for a different Piezas (say production, when this build targets
// staging) does not count: commands would send its token to the wrong place.
export function signInStatus(env = process.env) {
  const credentials = readCredentials(env);
  const target = resolveApiBase({}, env, TARGET_HOSTS[savedTarget(env)].api);
  if (!credentials) return { signedIn: false, target };
  const apiBase = (credentials.apiBase ?? DEFAULT_API_BASE_URL).replace(/\/+$/, '');
  return {
    signedIn: apiBase === target,
    otherPiezas: apiBase === target ? undefined : apiBase,
    email: credentials.email ?? null,
    tenantName: credentials.tenantName ?? null,
    target,
  };
}

// signInMismatch: the saved sign-in is for one Piezas (production or staging)
// while this computer is set to use the other. Commands must not quietly use
// the other environment, so they stop and ask for a fresh sign-in. Only the
// two real environments count; other hosts (development, tests) never match.
export function signInMismatch(env = process.env, options = {}) {
  const credentials = readCredentials(env);
  if (!credentials || typeof credentials.apiBase !== 'string') return null;
  const known = Object.values(TARGET_HOSTS).map((h) => h.api);
  const saved = credentials.apiBase.replace(/\/+$/, '');
  if (!known.includes(saved)) return null;
  const target = savedTarget(env);
  const active = resolveApiBase(options, env, TARGET_HOSTS[target].api);
  if (!known.includes(active) || active === saved) return null;
  return { signedInTo: saved, active, loginFlag: target === 'staging' ? ' --staging' : ' --production' };
}

// signInNeededLine: the one plain line commands print when they need an account.
export function signInNeededLine(env = process.env, options = {}) {
  const mismatch = signInMismatch(env, options);
  if (mismatch) {
    return `You're signed in to ${mismatch.signedInTo}, but this computer is set to use ${mismatch.active}. ` +
      `Sign in again for that Piezas: run \`npx piezas login${mismatch.loginFlag}\`, then retry.`;
  }
  return 'You need to sign in first: run `npx piezas login`, then retry.';
}

export function whoami(options = {}) {
  const env = options.env ?? process.env;
  const credentials = readCredentials(env);
  if (!credentials) {
    if (options.json) {
      console.log(JSON.stringify({ command: 'whoami', loggedIn: false }, null, 2));
    } else {
      console.log('  Not logged in. Run `npx piezas login` to sign in.');
    }
    return { exitCode: 1, command: 'whoami', loggedIn: false };
  }

  // Never include the cliToken here — whoami output is safe to paste anywhere.
  const summary = {
    command: 'whoami',
    loggedIn: true,
    tenantId: credentials.tenantId ?? null,
    tenantName: credentials.tenantName ?? null,
    email: credentials.email ?? null,
    apiBase: credentials.apiBase ?? DEFAULT_API_BASE_URL,
    matchesThisSetup: signInStatus(env).signedIn,
  };
  if (options.json) {
    console.log(JSON.stringify(summary, null, 2));
  } else {
    console.log('\n  🧱 Piezas CLI session\n');
    console.log(`  Tenant: ${summary.tenantName ?? 'unknown'}${summary.tenantId ? ` (${summary.tenantId})` : ''}`);
    console.log(`  Email:  ${summary.email ?? 'unknown'}`);
    console.log(`  API:    ${summary.apiBase}\n`);
    if (!summary.matchesThisSetup) {
      console.log(`  This setup uses ${resolveApiBase({}, env)}. Run \`piezas login\` to sign in there.\n`);
    }
  }
  return { exitCode: 0, ...summary };
}

// slugifyAppName mirrors the Go control plane's slugify (and the dashboard
// BFF): lowercase, [a-z0-9] runs joined by single hyphens, trimmed.
export function slugifyAppName(name) {
  return name
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

// resolveKeyViaLogin: when no key was found by the normal intake chain but a
// CLI session exists, create the app (or reuse it on a name conflict) and
// mint a live key bound to it — the same composition the dashboard's
// onboarding performs. Every failure degrades to "no key" with a friendly
// message; init never crashes because of this step.
export async function resolveKeyViaLogin(projectDir, options) {
  if (!options.fromLogin && !(options.interactive && !options.yes)) return undefined;
  const env = options.env ?? process.env;
  const credentials = platformCredentials(projectDir, env);
  if (!credentials) {
    if (signInMismatch(env, options)) log(`  ${signInNeededLine(env, options)}`);
    return undefined;
  }

  const flagApp = (typeof options.app === 'string' && options.app.trim())
    ? options.app.trim()
    : undefined;
  const defaultName = flagApp || basename(projectDir);
  let appName = defaultName;

  // Interactive (and not the non-interactive --from-login shortcut, and no
  // explicit --app): offer an explicit choice -- create a new app now (which
  // mints its key for you), or paste a key you already made in the dashboard.
  // Choosing "paste" (2) returns undefined so the caller falls through to the
  // paste prompt. Choosing "create" (1, the default) asks for the app name and
  // mints its key here -- no dashboard visit. An explicit --app skips the menu
  // and creates that app directly.
  if (!flagApp && !options.fromLogin && options.interactive && !options.yes) {
    const promptFn = options.promptFn ?? promptViaTerminal;
    log('');
    log(`  Signed in as ${credentials.email}. How would you like to get your API key?`);
    log("    1) Create a new app now - we'll mint its key  (recommended)");
    log('    2) Paste a key you already created in the dashboard');
    const choice = String((await promptFn('  Choose 1 or 2 [1]: ')) ?? '').trim();
    if (choice === '2') return undefined;
    const answer = String((await promptFn(`  Name for the new app [${defaultName}]: `)) ?? '').trim();
    appName = answer || defaultName;
  }

  const fetchFn = platformFetch(projectDir, options);
  const apiBase = resolveApiBase(options, env, credentials.apiBase || DEFAULT_API_BASE_URL);
  const admin = adminBaseUrl(apiBase);
  const tenantPath = `${admin}/v1/tenants/${credentials.tenantId}`;
  const httpOptions = { token: credentials.cliToken, timeoutMs: options.httpTimeoutMs };
  const sessionExpired = () => {
    log('  Your Piezas session has expired - run `npx piezas login`, then rerun init.');
    return undefined;
  };

  try {
    let app;
    const created = await fetchJson(fetchFn, `${tenantPath}/partitions`, {
      ...httpOptions,
      method: 'POST',
      body: { name: appName },
    });
    if (created.status === 201 && created.data?.id) {
      app = created.data;
      detail(`  Created app "${app.name}"${credentials.tenantName ? ` in ${credentials.tenantName}` : ''}`);
    } else if (created.status === 409) {
      // The app already exists — find it by the same slug the platform
      // derived (or by exact name) and reuse it, exactly like the dashboard.
      // LIST via my-apps (an admin sees all; create already proved admin here).
      const listed = await fetchJson(fetchFn, `${tenantPath}/my-apps`, httpOptions);
      if (listed.status === 401) return sessionExpired();
      const slug = slugifyAppName(appName);
      const existing = Array.isArray(listed.data?.data)
        ? listed.data.data.find((p) => p?.slug === slug || p?.name === appName)
        : undefined;
      if (!existing) {
        log('  An app with that name already exists but could not be found - continuing without a key.');
        return undefined;
      }
      app = existing;
      log(`  Reusing existing app "${app.name}"`);
    } else if (created.status === 401) {
      return sessionExpired();
    } else if (created.status === 403) {
      // Creating an app is admin-only — don't pretend a developer can self-serve.
      log('  Only an admin can create an app — ask an admin to create it and grant you');
      log('  access, then rerun init (or paste an existing key). Continuing without a key.');
      return undefined;
    } else {
      log(`  Could not create the app (HTTP ${created.status}) - continuing without a key.`);
      return undefined;
    }

    const minted = await fetchJson(fetchFn, `${tenantPath}/api-keys`, {
      ...httpOptions,
      method: 'POST',
      body: { name: appName, environment: 'live', partitionId: app.id },
    });
    if (minted.status === 401) return sessionExpired();
    if (minted.status !== 201 || typeof minted.data?.key !== 'string' || !minted.data.key) {
      log(`  Could not mint an API key (HTTP ${minted.status}) - continuing without a key.`);
      return undefined;
    }
    detail(`  Minted a live API key for "${app.name}"`);

    // Provision the HOSTED environment at birth: stage the freshly-minted key
    // into the apps server's cloud env store, bound to the app's durable id.
    // Best-effort — hosting may not be provisioned in every install — and the
    // local .env copy remains for LOCAL development only; deploys never read it.
    try {
      const appsBase = appsBaseUrl(options, env);
      const stagedRes = await fetchJson(fetchFn,
        `${appsBase}/v1/deployments/${slugifyAppName(app.name)}/env?appId=${encodeURIComponent(app.id)}`,
        { token: credentials.cliToken, method: 'PATCH', body: { set: { PIEZAS_API_KEY: minted.data.key } }, timeoutMs: 4000 });
      if (stagedRes.status === 200) {
        detail('  Hosted env provisioned — PIEZAS_API_KEY is already staged for deploys');
      }
    } catch { /* hosting is optional at init time */ }

    return { key: minted.data.key, source: 'login', appName: app.name, appId: app.id };
  } catch (error) {
    log(`  Could not reach Piezas (${error?.message || 'network error'}) - continuing without a key.`);
    return undefined;
  }
}

// --- End platform auth ---------------------------------------------------

// --- piezas deploy: ship the built app to the shared apps server ----------

export const DEFAULT_APPS_URL = TARGET.apps;
export const DEPLOY_TIMEOUT_MS = 10 * 60 * 1000; // uploads can be slow; be patient
// Client-side artifact cap — a FAST-FAIL courtesy so an oversized bundle is
// caught before a slow upload. Piezas hosting enforces its own limit
// server-side and is the authoritative check; this only exists to save
// a doomed round-trip. Configurable via PIEZAS_MAX_ARTIFACT_MB so it tracks the
// server default and can be raised without a CLI release. A full Piezas app
// (Next standalone) is ~10 MB compressed, so blowing this almost always means
// node_modules or media that belongs in the Documents service.
export function resolveMaxArtifactMB(env = process.env) {
  const raw = Number(env.PIEZAS_MAX_ARTIFACT_MB);
  return Number.isFinite(raw) && raw > 0 ? raw : 60;
}

export function appsBaseUrl(options, env) {
  const flag = typeof options.appsUrl === 'string' && options.appsUrl.trim()
    ? options.appsUrl.trim() : undefined;
  const fromEnv = typeof env.PIEZAS_APPS_URL === 'string' && env.PIEZAS_APPS_URL.trim()
    ? env.PIEZAS_APPS_URL.trim() : undefined;
  return (flag || fromEnv || DEFAULT_APPS_URL).replace(/\/+$/, '');
}

// deploySlugFor mirrors the server's base slugify so status/logs/delete can
// address the deployment. The authoritative (possibly suffixed) slug returned
// by a deploy is persisted into piezas.manifest.json for later commands.
export function deploySlugFor(projectDir, options) {
  const manifestPath = resolve(projectDir, 'piezas.manifest.json');
  let manifest = null;
  try { manifest = readJsonFile(manifestPath); } catch { /* absent/corrupt is fine */ }
  if (manifest?.deploy?.slug && !options.app) return manifest.deploy.slug;
  const name = (typeof options.app === 'string' && options.app.trim())
    ? options.app.trim()
    : manifest?.appName || basename(projectDir);
  return name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
}

// stageArtifact assembles the deployable tree in a temp dir and detects the
// app's shape (preflight, part 1), in priority order:
//   - --dir <path>: server.js -> server, index.html -> static
//   - Next standalone output                          -> kind "server"
//   - static export (out/ or dist/ with index.html)   -> kind "static"
//   - plain app at the project root (server.js / index.html) — LAST, so real
//     framework projects prefer their build output over their source tree
// Returns null when nothing deployable exists (with build guidance).
export function stageArtifact(projectDir, stagingDir, options) {
  const copyInto = (src) => execSync(`cp -R ${JSON.stringify(src)}/. ${JSON.stringify(stagingDir)}/`);
  // Every artifact is scrubbed, whatever its shape: no .env or .env.* file
  // (examples included) and no .git, at ANY depth. Build output is not clean
  // by itself: `next build` with output: "standalone" copies the project's
  // .env files into .next/standalone/, and server.js loads them at startup.
  const done = (result) => (result ? { ...result, removed: scrubArtifact(stagingDir) } : null);
  const stageFolder = (src, source) => {
    copyInto(src);
    if (existsSync(resolve(stagingDir, 'server.js'))) return done({ kind: 'server', source });
    if (existsSync(resolve(stagingDir, 'index.html'))) return done({ kind: 'static', source });
    return null; // has neither entry file -> caller explains
  };

  if (typeof options.dir === 'string' && options.dir.trim()) {
    const src = resolve(projectDir, options.dir.trim());
    if (!existsSync(src)) return null;
    return stageFolder(src, options.dir.trim());
  }

  const standalone = resolve(projectDir, '.next', 'standalone');
  if (existsSync(resolve(standalone, 'server.js'))) {
    copyInto(standalone);
    const staticDir = resolve(projectDir, '.next', 'static');
    if (existsSync(staticDir)) {
      mkdirSync(resolve(stagingDir, '.next'), { recursive: true });
      execSync(`cp -R ${JSON.stringify(staticDir)} ${JSON.stringify(resolve(stagingDir, '.next', 'static'))}`);
    }
    const publicDir = resolve(projectDir, 'public');
    if (existsSync(publicDir)) {
      execSync(`cp -R ${JSON.stringify(publicDir)} ${JSON.stringify(resolve(stagingDir, 'public'))}`);
    }
    return done({ kind: 'server', source: 'next standalone' });
  }

  // Static exports: Next `output: "export"` writes out/, Vite writes dist/.
  for (const candidate of ['out', 'dist']) {
    const src = resolve(projectDir, candidate);
    if (existsSync(resolve(src, 'index.html'))) {
      copyInto(src);
      return done({ kind: 'static', source: `${candidate}/` });
    }
  }

  // Plain app at the project root — a bare `deploy` should just work when
  // server.js (or index.html) sits right there.
  if (existsSync(resolve(projectDir, 'server.js')) || existsSync(resolve(projectDir, 'index.html'))) {
    return stageFolder(projectDir, 'project root');
  }
  return null;
}

// scrubArtifact removes local-only files from a staged artifact, at any depth:
// every .env and .env.* (templates like .env.example too: the running app
// never needs them, and people do put real values in them) and every .git.
// Symlinks are removed as entries, never followed. Returns the removed paths,
// relative to the artifact root, for the one-line notice.
export function scrubArtifact(root) {
  const removed = [];
  const walk = (dir) => {
    let entries;
    try { entries = readdirSync(dir, { withFileTypes: true }); } catch { return; }
    for (const entry of entries) {
      const full = join(dir, entry.name);
      if (entry.name === '.git' || entry.name === '.env' || entry.name.startsWith('.env.')) {
        rmSync(full, { recursive: true, force: true });
        removed.push(relative(root, full));
      } else if (entry.isDirectory() && !entry.isSymbolicLink()) {
        walk(full);
      }
    }
  };
  walk(root);
  return removed.sort();
}

// detectStaleBuild (CLI-1): `deploy` ships the LAST build as-is — it never
// builds. That contract is invisible in the happy path (users build right
// before deploying) and bites exactly when a dependency or source file changed
// under an existing build: the deploy silently ships old code. Compare the
// build marker's mtime against the newest source file and warn.
// Returns { stale, buildPath, buildMtimeMs, newestSourcePath, newestSourceMtimeMs }
// or null when there is no separate build to compare (no artifact yet, or the
// project root IS the artifact so "source vs build" is meaningless).
export function detectStaleBuild(projectDir, options = {}) {
  // Resolve the build marker with the same search order stageArtifact uses.
  let buildPath = null;
  let excludeDir = null;
  if (typeof options.dir === 'string' && options.dir.trim()) {
    const src = resolve(projectDir, options.dir.trim());
    for (const marker of ['server.js', 'index.html']) {
      if (existsSync(resolve(src, marker))) { buildPath = resolve(src, marker); break; }
    }
    excludeDir = src;
  } else if (existsSync(resolve(projectDir, '.next', 'standalone', 'server.js'))) {
    buildPath = resolve(projectDir, '.next', 'standalone', 'server.js');
  } else {
    for (const candidate of ['out', 'dist']) {
      if (existsSync(resolve(projectDir, candidate, 'index.html'))) {
        buildPath = resolve(projectDir, candidate, 'index.html');
        break;
      }
    }
  }
  if (!buildPath) return null;
  const buildMtimeMs = statSync(buildPath).mtimeMs;

  // Newest source file: walk the project, skipping build outputs and noise.
  // Bounded (files + depth) so a huge tree can't stall the deploy.
  const skip = new Set([...DEFAULT_EXCLUDED_DIRS, '.vercel', '.cache']);
  let newest = { path: null, mtimeMs: 0 };
  let budget = 4000;
  const walk = (d, depth) => {
    if (budget <= 0 || depth > 8) return;
    let entries;
    try { entries = readdirSync(d, { withFileTypes: true }); } catch { return; }
    for (const entry of entries) {
      if (budget-- <= 0) return;
      const full = join(d, entry.name);
      if (entry.isDirectory()) {
        if (skip.has(entry.name) || (excludeDir && full === excludeDir)) continue;
        walk(full, depth + 1);
      } else if (entry.isFile()) {
        if (entry.name === '.env' || entry.name.startsWith('.env.')) continue;
        if (!TEXT_EXTENSIONS.has(extname(entry.name))) continue;
        try {
          const m = statSync(full).mtimeMs;
          if (m > newest.mtimeMs) newest = { path: full, mtimeMs: m };
        } catch { /* raced away */ }
      }
    }
  };
  walk(projectDir, 0);
  if (!newest.path) return null;

  // 2s slack: build outputs are written moments after the last source touch.
  return {
    stale: newest.mtimeMs > buildMtimeMs + 2000,
    buildPath,
    buildMtimeMs,
    newestSourcePath: newest.path,
    newestSourceMtimeMs: newest.mtimeMs,
  };
}

// sdkVersionNudge (CLI-1): a fixed @piezas/sdk only reaches production when the
// app updates + rebuilds + redeploys — and nothing tells users a fix exists.
// Best-effort, never blocks: any failure (offline, timeout, no dep) => null.
export async function sdkVersionNudge(projectDir, fetchFn = fetch) {
  let installed;
  try {
    const pkg = readJsonFile(resolve(projectDir, 'package.json'));
    const spec = pkg.dependencies?.['@piezas/sdk'] ?? pkg.devDependencies?.['@piezas/sdk'];
    if (!spec) return null;
    // Local/workspace links track the repo, not npm — a registry nudge is noise.
    if (/^(file:|link:|workspace:)/.test(spec)) return null;
    installed = readJsonFile(
      resolve(projectDir, 'node_modules', '@piezas', 'sdk', 'package.json'),
    ).version;
    if (!installed) return null;
  } catch { return null; }

  try {
    const ac = new AbortController();
    const timer = setTimeout(() => ac.abort(), 2000);
    const res = await netFetch(fetchFn, 'https://registry.npmjs.org/@piezas/sdk/latest', {
      signal: ac.signal,
      headers: { Accept: 'application/json' },
    });
    clearTimeout(timer);
    if (!res.ok) return null;
    const latest = (await res.json())?.version;
    if (!latest) return null;
    const lt = (a, b) => {
      const pa = String(a).split('.').map(Number);
      const pb = String(b).split('.').map(Number);
      for (let i = 0; i < 3; i++) {
        if ((pa[i] || 0) !== (pb[i] || 0)) return (pa[i] || 0) < (pb[i] || 0);
      }
      return false;
    };
    if (!lt(installed, latest)) return null;
    return (
      `  ℹ @piezas/sdk ${installed} is installed; ${latest} is available with fixes.\n` +
      `     npm install @piezas/sdk@latest   then rebuild and deploy again.`
    );
  } catch { return null; }
}

// hasPiezasEvidence: the shared apps server hosts PIEZAS apps, not arbitrary
// sites. A real Piezas app leaves fingerprints in its build — the traced
// @piezas/sdk in standalone output, or api.piezas.ai / PIEZAS_API_KEY
// references in its code. This client check gives instant feedback; the
// server runs the same check authoritatively.
export function hasPiezasEvidence(dir) {
  if (existsSync(resolve(dir, 'node_modules', '@piezas', 'sdk', 'package.json'))) {
    return true;
  }
  const markers = ['api.piezas.ai', '@piezas/sdk', 'PIEZAS_API_KEY'];
  const exts = new Set(['.js', '.mjs', '.cjs', '.html', '.json']);
  let budget = 64 * 1024 * 1024; // hard scan bound
  const walk = (d) => {
    for (const entry of readdirSync(d)) {
      if (entry === 'node_modules') continue; // third-party noise; SDK checked above
      const full = join(d, entry);
      const st = statSync(full);
      if (st.isDirectory()) {
        if (walk(full)) return true;
        continue;
      }
      if (!exts.has(extname(entry).toLowerCase()) || st.size > 4 * 1024 * 1024) continue;
      if ((budget -= st.size) < 0) return false;
      const content = readFileSync(full, 'utf-8');
      if (markers.some((m) => content.includes(m))) return true;
    }
    return false;
  };
  try {
    return walk(dir);
  } catch {
    return true; // scanning trouble must not block a legitimate deploy — the server re-checks
  }
}

// detectOtherRuntime names the ecosystem when a project clearly isn't a
// Node/static app, so the "can't deploy" message can be honest and specific
// instead of offering Next.js advice to a Python developer.
export function detectOtherRuntime(projectDir) {
  const signals = [
    ['requirements.txt', 'Python'],
    ['pyproject.toml', 'Python'],
    ['Pipfile', 'Python'],
    ['go.mod', 'Go'],
    ['Cargo.toml', 'Rust'],
    ['Gemfile', 'Ruby'],
    ['composer.json', 'PHP'],
    ['pom.xml', 'Java'],
    ['build.gradle', 'Java'],
  ];
  for (const [file, runtime] of signals) {
    if (existsSync(resolve(projectDir, file))) return runtime;
  }
  return null;
}

// findNextConfig returns the Next config the project ACTUALLY has (first match
// wins, the way Next itself resolves it). Both the deploy diagnosis and the
// doctor preflight name that exact file — generic advice about "next.config" is
// what left users editing the wrong thing.
export const NEXT_CONFIG_FILES = ['next.config.js', 'next.config.mjs', 'next.config.ts'];

export function findNextConfig(projectDir) {
  for (const name of NEXT_CONFIG_FILES) {
    const path = resolve(projectDir, name);
    if (!existsSync(path)) continue;
    let text = '';
    try { text = readFileSync(path, 'utf-8'); } catch { /* unreadable -> treat as empty */ }
    return { name, path, text };
  }
  return null;
}

// diagnoseNextBuild explains THE deploy-day trap: `npm run build` succeeds,
// `next dev`/`next start` work for days, but next.config never set
// output: 'standalone' — so no .next/standalone/server.js exists and there is
// nothing to ship. Nothing before deploy day needs that line, which is exactly
// why it goes missing. Returns null unless a Next build ran (.next/ present)
// AND a config file exists to name; the generic guidance covers everything else.
export function diagnoseNextBuild(projectDir) {
  if (!existsSync(resolve(projectDir, '.next'))) return null;
  const config = findNextConfig(projectDir);
  if (!config) return null;
  return {
    status: config.text.includes('standalone') ? 'rebuild-needed' : 'standalone-missing',
    configFile: config.name,
  };
}

// collectExplicitEnv: deploy NEVER reads the local .env file — the hosted
// runtime's environment lives in the cloud store (console-managed, or staged
// at app creation). The only env that travels with a deploy is what the user
// consciously types as --env KEY=VALUE (the Heroku config:set posture). This
// is a security property, not a convenience trade-off: the CLI has no code
// path that opens .env, so no bug or compromised release can exfiltrate it.
// askReportButton gets this deploy's answer to "Keep the Report a problem
// button on?" and saves it in the manifest as the next default.
// Returns { ok: true, value: 'on'|'off' } or { ok: false, status }.
export async function askReportButton(projectDir, options = {}) {
  const manifestPath = resolve(projectDir, 'piezas.manifest.json');
  let manifest = null;
  try { manifest = readJsonFile(manifestPath); } catch { manifest = null; }
  const last = manifest?.reportButton === false ? 'off' : 'on';
  let value;
  if (options.reportButton !== undefined) {
    value = String(options.reportButton).trim().toLowerCase();
    if (value !== 'on' && value !== 'off') {
      log('  --report-button must be on or off.\n');
      return { ok: false, status: 'report-button-invalid' };
    }
  } else if (options.interactive && options.promptFn !== null) {
    const promptFn = options.promptFn ?? promptViaTerminal;
    const hint = last === 'on' ? '(Y/n)' : '(y/N)';
    const a = String((await promptFn(`  Keep the Report a problem button on? ${hint} `)) ?? '').trim().toLowerCase();
    value = a === '' ? last : (a === 'y' || a === 'yes') ? 'on' : (a === 'n' || a === 'no') ? 'off' : null;
    if (!value) {
      log('  Please answer y or n. Nothing was deployed.\n');
      return { ok: false, status: 'report-button-invalid' };
    }
  } else {
    log('  Before every deploy the owner must be asked: keep the Report a problem button on?');
    log('  Then deploy with --report-button on or --report-button off.\n');
    return { ok: false, status: 'report-button-required' };
  }
  if (manifest) {
    const before = manifest.reportButton;
    if (value === 'off') manifest.reportButton = false;
    else delete manifest.reportButton;
    if (before !== manifest.reportButton) writeFileSync(manifestPath, `${JSON.stringify(manifest, null, 2)}\n`);
  }
  log(`  Report a problem button: ${value}`);
  return { ok: true, value };
}

export function collectExplicitEnv(options) {
  const sent = {};
  const pairs = Array.isArray(options.envPairs) ? options.envPairs : options.envPairs ? [options.envPairs] : [];
  for (const pair of pairs) {
    const m = /^([A-Za-z_][A-Za-z0-9_]*)=([\s\S]*)$/.exec(String(pair));
    if (m) sent[m[1]] = m[2];
  }
  return sent;
}

// mintAndStageHostedKey mints a live API key for the app (the same
// control-plane call init uses) and stages it into the HOSTED env store —
// bound by durable id, value never shown, never written to any local file.
// Returns { ok, stage, status }: ok=true when the hosted env ends up holding
// PIEZAS_API_KEY; on failure, `stage` names which half broke ('mint' at the
// control plane, or 'stage' at the apps-server) and `status` is its HTTP code,
// so callers can tell the user WHY instead of a bare "could not mint".
export async function mintAndStageHostedKey(linked, credentials, options, fetchFn) {
  const env = options.env ?? process.env;
  const apiBase = resolveApiBase(options, env, credentials.apiBase || DEFAULT_API_BASE_URL);
  const minted = await fetchJson(fetchFn,
    `${adminBaseUrl(apiBase)}/v1/tenants/${credentials.tenantId}/api-keys`, {
      token: credentials.cliToken,
      timeoutMs: options.httpTimeoutMs,
      method: 'POST',
      body: { name: linked.appName, environment: 'live', partitionId: linked.appId },
    });
  if (minted.status !== 201 || typeof minted.data?.key !== 'string' || !minted.data.key) {
    return { ok: false, stage: 'mint', status: minted.status };
  }
  const base = appsBaseUrl(options, env);
  const stagedRes = await fetchJson(fetchFn,
    `${base}/v1/deployments/${slugifyAppName(linked.appName)}/env?appId=${encodeURIComponent(linked.appId)}`, {
      token: credentials.cliToken,
      method: 'PATCH',
      body: { set: { PIEZAS_API_KEY: minted.data.key } },
      timeoutMs: 8000,
    });
  return { ok: stagedRes.status === 200, stage: 'stage', status: stagedRes.status };
}

// ensureAppLink resolves this project's durable app identity (the control
// plane app/partition UUID), EB-style: prefer the binding already recorded in
// piezas.manifest.json (deploy.appId, written by init); otherwise pull the
// tenant's app NAMES from the platform and let the user pick — confirming
// identity from the web without any secret involved — then persist the
// binding. Returns null when unlinked and unable to ask.
export async function ensureAppLink(projectDir, options, credentials, fetchFn) {
  const manifestPath = resolve(projectDir, 'piezas.manifest.json');
  let manifest = null;
  try { manifest = readJsonFile(manifestPath); } catch { /* no manifest yet */ }
  if (manifest?.deploy?.appId) {
    return { appId: manifest.deploy.appId, appName: manifest.appName || basename(projectDir) };
  }

  const env = options.env ?? process.env;
  const apiBase = resolveApiBase(options, env, credentials.apiBase || DEFAULT_API_BASE_URL);
  const adminBase = adminBaseUrl(apiBase);
  // LIST via my-apps: it returns the CALLER's apps — an admin sees all, a
  // developer sees only granted apps — so the picker works for both roles with
  // no client-side role logic. CREATE still targets /partitions (admin-only).
  const myAppsUrl = `${adminBase}/v1/tenants/${credentials.tenantId}/my-apps`;
  const partitionsUrl = `${adminBase}/v1/tenants/${credentials.tenantId}/partitions`;
  const httpOptions = { token: credentials.cliToken, timeoutMs: options.httpTimeoutMs };
  let apps = [];
  let listFailed = false;   // a genuine network failure — the platform was unreachable
  let authFailed = false;   // 401/403 — the session isn't authorized or has expired
  try {
    const res = await fetchJson(fetchFn, myAppsUrl, httpOptions);
    if (res.status === 200 && Array.isArray(res.data?.data)) apps = res.data.data;
    else if (res.status === 401 || res.status === 403) authFailed = true;
    else listFailed = true;
  } catch {
    listFailed = true;
  }

  // --app <name>: auto-link on an exact name/slug match, no prompt needed.
  const wanted = typeof options.app === 'string' && options.app.trim() ? options.app.trim() : null;
  if (wanted) {
    const slug = wanted.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
    const hit = apps.find((a) => a.slug === slug || a.name === wanted);
    if (hit) return persistAppLink(manifestPath, manifest, hit);
  }

  const interactive = options.interactive && options.promptFn !== null;
  const promptFn = options.promptFn ?? promptViaTerminal;

  // createApp: a fresh account (or a deliberate choice) creates the app right
  // here — same control-plane call init uses. No key is minted (that's init's
  // job); hosting only needs the app record to exist.
  const createApp = async () => {
    const def = wanted || manifest?.appName || basename(projectDir);
    const answer = String((await promptFn(`  App name [${def}]: `)) ?? '').trim();
    const name = answer || def;
    const res = await fetchJson(fetchFn, partitionsUrl, { ...httpOptions, method: 'POST', body: { name } });
    if (res.status === 201 && res.data?.id) {
      log(`  Created app "${res.data.name}" — it's in your console now.`);
      const link = persistAppLink(manifestPath, manifest, res.data);
      // App creation provisions the key — same behavior as init and the
      // console welcome flow. The hosted env holds it before first boot.
      if (link) {
        const staged = await mintAndStageHostedKey(link, credentials, options, fetchFn);
        if (staged.ok) {
          log('  Minted its API key and staged it in the hosted environment.');
          log('  (For local development, run `npx piezas init` to write a key into .env.)');
          return { ...link, keyStaged: true };
        }
        log(`  Could not mint/stage its API key automatically (${staged.stage} HTTP ${staged.status}) — you'll be asked before deploy.`);
      }
      return link;
    }
    if (res.status === 401) {
      log('  Your session has expired — run `npx piezas login`, then retry.\n');
      return null;
    }
    if (res.status === 403) {
      // Creating an app is admin-only. A developer who reaches here (empty list,
      // or chose "+ Create") is NOT looped on a dead end — tell them the truth
      // and exactly what unblocks them. Point at an admin; don't imply self-serve.
      log('  Only an admin can create an app, so it can\'t be created from here.');
      log('  Ask an admin to create it (in the console, or from their own CLI) and grant');
      log('  you access. Once you\'re granted, `npx piezas deploy` will find it here.\n');
      return null;
    }
    if (res.status === 409) {
      // Name already taken in this tenant — link to the existing app instead.
      try {
        const l = await fetchJson(fetchFn, myAppsUrl, httpOptions);
        const slug = name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
        const hit = (l.data?.data ?? []).find((a) => a.slug === slug || a.name === name);
        if (hit) {
          log(`  App "${hit.name}" already exists — linking this project to it.`);
          return persistAppLink(manifestPath, manifest, hit);
        }
      } catch { /* fall through */ }
    }
    log(`  Could not create the app (HTTP ${res.status}) — try again, or create it in the console.\n`);
    return null;
  };

  // Honest, distinct outcomes when the list yielded nothing to auto-pick from.
  // These are checked in order and each is DIFFERENT from a network failure:
  //   authFailed → the session, not the connection (never "check your connection")
  //   listFailed → a genuine network/unreachable failure (keep the old copy)
  //   empty list → NOT an error: fall through to create; a developer's create
  //                403s into the honest "ask your admin" message (no dead-end loop).
  if (authFailed) {
    log('  Your Piezas session isn\'t authorized (it may have expired) — run `npx piezas login`, then retry.\n');
    return null;
  }
  if (listFailed) {
    log(`  Could not reach ${apiBase} to look up your apps — check your connection and retry.\n`);
    return null;
  }

  if (interactive) {
    if (!apps.length) {
      // Could be a brand-new admin (create succeeds) or a developer with no
      // grants yet (create 403s → "ask your admin"). createApp() branches on the
      // response — either way, there is no dead-end loop.
      return await createApp();
    }
    log('  Which app is this project? (identity confirmed from your account — nothing is uploaded)');
    apps.forEach((a, i) => log(`    ${i + 1}) ${a.name}`));
    log(`    ${apps.length + 1}) + Create a new app`);
    const answer = String((await promptFn(`  Choose 1-${apps.length + 1}: `)) ?? '').trim();
    const idx = Number(answer) - 1;
    if (Number.isInteger(idx) && idx >= 0 && idx < apps.length) {
      return persistAppLink(manifestPath, manifest, apps[idx]);
    }
    if (idx === apps.length) {
      return await createApp();
    }
  }

  log('  This project is not linked to an app yet.');
  log('  Run `npx piezas deploy` from a terminal (interactive) to link or create one,');
  log('  or set deploy.appId in piezas.manifest.json to your app\'s id.\n');
  return null;
}

// persistAppLink records the confirmed identity in the manifest.
export function persistAppLink(manifestPath, manifest, app) {
  try {
    const m = manifest ?? {};
    m.appName = app.name;
    m.deploy = { ...(m.deploy || {}), appId: app.id };
    writeFileSync(manifestPath, `${JSON.stringify(m, null, 2)}\n`);
    log(`  Linked to "${app.name}" (${app.id.slice(0, 8)}…) — recorded in piezas.manifest.json`);
  } catch { /* linking is a convenience record; deploy still carries the id */ }
  return { appId: app.id, appName: app.name };
}

// persistDeploySlug records the server-assigned slug + URL in the manifest so
// later `deploy --status/--logs/--delete` target the right deployment.
export function persistDeploySlug(projectDir, slug, url) {
  const manifestPath = resolve(projectDir, 'piezas.manifest.json');
  try {
    const manifest = readJsonFile(manifestPath);
    manifest.deploy = { ...(manifest.deploy || {}), mode: 'mixed', slug, url };
    writeFileSync(manifestPath, `${JSON.stringify(manifest, null, 2)}\n`);
  } catch {
    // No manifest (deploy outside an init'd project): skip — slug can still be
    // re-derived from the app name.
  }
}

export async function deploy(options = {}) {
  const env = options.env ?? process.env;
  const projectDir = options.cwd || process.cwd();
  const fetchFn = platformFetch(projectDir, options);
  const sandbox = isSandboxProject(projectDir);
  const base = appsBaseUrl(options, env);

  log('\n  🧱 Piezas deploy\n');

  if (sandbox) log(`  ${SANDBOX_NOTE}\n`);

  if (options.isolated) {
    log('  --isolated gives your app its own infrastructure: a dedicated server,');
    log('  private network, its own database, storage, and access logs — nothing');
    log('  shared with anyone. It\'s how our compliance-heavy clients run today.');
    log('');
    log('  It\'s coming soon. Right now `npx piezas deploy` ships to the shared');
    log('  apps server (--mixed): up to 2 apps free, isolated containers.');
    log('');
    log('  Want early access to isolated mode?  https://app.piezas.ai/contact\n');
    return { exitCode: 1, command: 'deploy', status: 'unsupported-mode' };
  }

  const credentials = platformCredentials(projectDir, env);
  if (!credentials) {
    log(`  ${signInNeededLine(env, options)}\n`);
    return { exitCode: 1, command: 'deploy', status: 'not-logged-in' };
  }
  const httpOptions = { token: credentials.cliToken, timeoutMs: options.httpTimeoutMs };
  const slug = deploySlugFor(projectDir, options);
  // The durable identity, if this project is linked; lookups prefer it over
  // the (rename-able) slug.
  const knownAppId = (() => {
    try { return readJsonFile(resolve(projectDir, 'piezas.manifest.json')).deploy?.appId ?? null; } catch { return null; }
  })();
  const idQS = knownAppId ? `?appId=${encodeURIComponent(knownAppId)}` : '';

  // --status / --logs / --delete address an existing deployment and skip packaging.
  if (options.status) {
    const res = await fetchJson(fetchFn, `${base}/v1/deployments/${slug}${idQS}`, httpOptions);
    if (res.status === 404) {
      log(`  No deployment named "${slug}" — run \`npx piezas deploy\` first.\n`);
      return { exitCode: 1, command: 'deploy', status: 'not-found', slug };
    }
    if (res.status !== 200) {
      log(`  Could not fetch status (HTTP ${res.status}).\n`);
      return { exitCode: 1, command: 'deploy', status: `http-${res.status}`, slug };
    }
    log(`  ${res.data.slug}: ${res.data.status}`);
    log(`  ${res.data.url}\n`);
    return { exitCode: 0, command: 'deploy', ...res.data };
  }
  if (options.logs) {
    // Bare `--logs` arrives as boolean true — and Number(true) is 1, which
    // would silently tail a single line. Explicit numbers only; else 200.
    const tail = options.logs !== true && Number.isFinite(Number(options.logs)) && Number(options.logs) > 0
      ? Number(options.logs) : 200;
    const res = await fetchJson(fetchFn,
      `${base}/v1/deployments/${slug}/logs?tail=${tail}${knownAppId ? `&appId=${encodeURIComponent(knownAppId)}` : ''}`,
      httpOptions);
    if (res.status !== 200) {
      log(`  Could not fetch logs (HTTP ${res.status}).\n`);
      return { exitCode: 1, command: 'deploy', status: `http-${res.status}`, slug };
    }
    console.log(res.data.logs || '(no output yet)');
    return { exitCode: 0, command: 'deploy', slug, status: 'logs' };
  }
  if (options.delete) {
    const res = await fetchJson(fetchFn, `${base}/v1/deployments/${slug}${idQS}`, { ...httpOptions, method: 'DELETE' });
    if (res.status === 404) {
      log(`  No deployment named "${slug}" — nothing to delete.\n`);
      return { exitCode: 1, command: 'deploy', status: 'not-found', slug };
    }
    if (res.status !== 200) {
      log(`  Could not delete (HTTP ${res.status}).\n`);
      return { exitCode: 1, command: 'deploy', status: `http-${res.status}`, slug };
    }
    log(`  Deleted "${slug}" from the apps server — its URL no longer serves.`);
    log('  (The app itself still exists in your console; delete it there if you');
    log('  want the app record and its keys gone too.)\n');
    return { exitCode: 0, command: 'deploy', status: 'deleted', slug };
  }

  // --- the deploy itself ---------------------------------------------------
  // Session preflight (fail fast, clear message). The apps-server accepts this
  // token by SIGNATURE alone, and a linked project reads its appId from the
  // local manifest — so a token whose control-plane SESSION is dead (revoked,
  // or rolled back by a DB restore) stays invisible until the key-mint 401s
  // deep in the flow, after packaging. One cheap authed GET surfaces it here.
  // Only a definitive 401/403 blocks; an unreachable/5xx control plane must
  // never gate a redeploy (the apps-server stays the authoritative enforcer).
  const apiBase = resolveApiBase(options, env, credentials.apiBase || DEFAULT_API_BASE_URL);
  try {
    // Reach my-apps (any tenant principal can), not partitions (admin-only): a
    // developer's VALID session must not read as "expired" here. A 401/403 from
    // my-apps is therefore a genuinely dead/unauthorized session, worth blocking.
    const ping = await fetchJson(fetchFn,
      `${adminBaseUrl(apiBase)}/v1/tenants/${credentials.tenantId}/my-apps`, httpOptions);
    if (ping.status === 401 || ping.status === 403) {
      log('  Your Piezas session has expired — run `npx piezas login`, then deploy again.');
      log(`  (the control plane rejected the saved token: HTTP ${ping.status})\n`);
      return { exitCode: 1, command: 'deploy', status: 'session-expired', httpStatus: ping.status };
    }
  } catch { /* control plane unreachable — do not gate; downstream calls enforce */ }

  // Identity first (EB-style): confirm WHICH app this is from the platform's
  // own list — by durable id, never by secret — before anything is packaged.
  const linked = await ensureAppLink(projectDir, options, credentials, fetchFn);
  if (!linked) {
    return { exitCode: 1, command: 'deploy', status: 'not-linked' };
  }

  // Hosted-state preflight, BEFORE any packaging: does this app already have a
  // deployment (redeploys are always allowed), and if not, is there a free
  // slot? Refusing here costs milliseconds; refusing after upload costs the
  // user a 50 MB round-trip. The server remains the authoritative enforcer.
  let hostedExists = false;
  let serverKeys = [];
  let hostedAuthFailed = false;   // 401/403 — the session is expired or absent
  try {
    const res = await fetchJson(fetchFn,
      `${base}/v1/deployments/${slug}?appId=${encodeURIComponent(linked.appId)}`, httpOptions);
    if (res.status === 200) {
      hostedExists = true;
      if (Array.isArray(res.data?.envKeys)) serverKeys = res.data.envKeys;
    } else if (res.status === 401 || res.status === 403) {
      hostedAuthFailed = true;
    }
  } catch { /* unreachable -> the server-side checks still hold */ }
  // A rejected session here reads the hosted env as EMPTY, which then misfires
  // the requiredEnv gate as "NOT SET" and blocks the deploy with a misleading
  // env message. ensureAppLink short-circuits on a cached appId, so this
  // preflight is often the FIRST authenticated call — the first place an expired
  // token surfaces. Tell the truth and stop before packaging + a 50 MB upload.
  if (hostedAuthFailed) {
    log('  Your Piezas session isn\'t valid (expired or logged out), so this app\'s');
    log('  hosted settings can\'t be read. Deploying now would wrongly report the');
    log('  environment as empty — run `npx piezas login`, then deploy again.\n');
    return { exitCode: 1, command: 'deploy', status: 'auth-expired' };
  }
  if (!hostedExists) {
    try {
      const lres = await fetchJson(fetchFn, `${base}/v1/deployments`, httpOptions);
      const lim = lres.status === 200 ? lres.data?.limits : null;
      // maxApps <= 0 = unlimited; only positive caps gate.
      if (lim && lim.maxApps > 0 && lim.used >= lim.maxApps) {
        log(`  Your plan already hosts ${lim.used} of ${lim.maxApps} apps — the --mixed limit.`);
        log('  Free a slot (delete an app from its console page), or get early access');
        log('  to dedicated infrastructure: https://app.piezas.ai/contact\n');
        return { exitCode: 1, command: 'deploy', status: 'limit-reached', limits: lim };
      }
    } catch { /* unreachable -> the server-side check still holds */ }
  }

  // The Report a problem button: the owner answers on EVERY deploy, and the
  // answer travels as the hosted setting PIEZAS_REPORT_BUTTON, which the app
  // reads at run time (no code change). Terminal: a prompt whose default is
  // the last answer. Anywhere else (AI tools, CI): --report-button is
  // required, because only the owner can answer.
  const reportChoice = await askReportButton(projectDir, options);
  if (!reportChoice.ok) return { exitCode: 1, command: 'deploy', status: reportChoice.status };

  // Env confirmation on EVERY interactive deploy — new code is exactly when
  // new variables appear, so the reminder rides along each time (one Enter
  // per deploy is cheap insurance against a drifted environment).
  // The platform CANNOT read local .env — by design, like Vercel/EB — so the
  // human vouches against the ACTUAL hosted names shown. CI/non-interactive
  // never blocks; requiredEnv remains the hard gate for declared vars.
  if (options.interactive && options.promptFn !== null) {
    const promptFn = options.promptFn ?? promptViaTerminal;
    log('  Quick settings check before deploying:');
    log('  Apps often need saved settings to work — API keys, passwords for other');
    log('  services (Stripe, OpenAI, ...), and other configuration. Developers call');
    log('  these "environment variables".');
    log('');
    log(`  Settings saved for your LIVE app right now:  ${serverKeys.length ? serverKeys.join(', ') : '(none yet)'}`);
    log('  The .env file on this computer stays private — we never read or upload');
    log('  it — so anything that is ONLY in that file will NOT reach your live app.');
    log('');
    log('  Need to add one?  Easiest:  app.piezas.ai -> your app -> Hosting -> Environment');
    log('                    Terminal: npx piezas env set NAME=value');
    const a = String((await promptFn('  Does your live app have every setting it needs? [Y/n]: ')) ?? '')
      .trim().toLowerCase();
    if (a === 'n' || a === 'no') {
      log('  Good call — add the settings, then run deploy again.\n');
      return { exitCode: 1, command: 'deploy', status: 'env-not-confirmed' };
    }
  } else if (serverKeys.length) {
    log(`  Live app settings: ${serverKeys.join(', ')} (the local .env file is never read)`);
  }

  // The deploy attestation (warn-only in v1). `npx piezas test` writes it; we
  // report it in one line and carry it to the platform, which is where
  // "untested cannot ship" will actually get teeth. Blocking here would only teach people to deploy around the CLI.
  const attestation = readTestAttestation(projectDir);
  const attestationNote = attestationWarning(attestation);
  if (attestationNote) log(`  ⚠ ${attestationNote}`);

  const { mkdtempSync, rmSync, statSync: stat } = await import('fs');
  const { tmpdir } = await import('os');
  const staging = mkdtempSync(join(tmpdir(), 'piezas-deploy-'));
  const tarball = join(tmpdir(), `piezas-artifact-${Date.now()}.tar.gz`);
  try {
    log('  Packaging your built app...');
    const staged = stageArtifact(projectDir, staging, options);
    if (!staged) {
      // A non-Node project deserves the truth, not Next.js build advice: the
      // shared apps server runs Node and static apps today. Other runtimes
      // arrive with dedicated infrastructure (--isolated / image deploys).
      const otherRuntime = detectOtherRuntime(projectDir);
      if (otherRuntime) {
        log(`  This looks like a ${otherRuntime} app. The shared apps server currently`);
        log('  runs Node.js and static apps — other runtimes are coming with dedicated');
        log('  infrastructure (--isolated).');
        log('');
        log('  Your app can still USE Piezas from any language — every service is a');
        log('  plain HTTPS API (https://api.piezas.ai/<service>/openapi.json). Hosting');
        log('  is the only Node-specific part today.');
        log('');
        log(`  Want ${otherRuntime} hosting early?  https://app.piezas.ai/contact\n`);
        return { exitCode: 1, command: 'deploy', status: 'unsupported-runtime', runtime: otherRuntime };
      }
      // A built Next app that produced no standalone server is not a "build
      // first" problem — the user already built. Name the file and the line.
      // (--dir points the deploy at an explicit folder, so the miss is that
      // folder, not the Next config.)
      const usingExplicitDir = typeof options.dir === 'string' && Boolean(options.dir.trim());
      const nextDiagnosis = usingExplicitDir ? null : diagnoseNextBuild(projectDir);
      if (nextDiagnosis?.status === 'standalone-missing') {
        log(`  Your Next build succeeded, but ${nextDiagnosis.configFile} does not set  output: 'standalone',`);
        log('  so the build never produced .next/standalone/server.js — the bundle deploy ships.');
        log('');
        log('  Fix (one line + rebuild):');
        log(`    1. add    output: 'standalone',   to the config object in ${nextDiagnosis.configFile}`);
        log('    2. npm run build');
        log('    3. npx piezas deploy\n');
        return {
          exitCode: 1,
          command: 'deploy',
          status: 'standalone-missing',
          configFile: nextDiagnosis.configFile,
        };
      }
      if (nextDiagnosis?.status === 'rebuild-needed') {
        log('  Rebuild needed: run  npm run build  then deploy again.');
        log(`  (${nextDiagnosis.configFile} is right — it sets output: 'standalone' — but`);
        log('  .next/standalone/server.js is missing or stale. Deploy ships the build');
        log('  output as-is; it never builds.)\n');
        return {
          exitCode: 1,
          command: 'deploy',
          status: 'rebuild-needed',
          configFile: nextDiagnosis.configFile,
        };
      }
      log('  Nothing deployable found. Build first:');
      log('    server app:  next.config output: "standalone"   then   npm run build');
      log('    static app:  a build that produces out/ or dist/ with index.html');
      log('  (or point at a folder with --dir <path> whose root has server.js or index.html)\n');
      return { exitCode: 1, command: 'deploy', status: 'no-artifact' };
    }
    if (!hasPiezasEvidence(staging)) {
      log('  This build doesn\'t reference Piezas anywhere — no @piezas/sdk, no');
      log('  api.piezas.ai calls. The free apps server hosts Piezas apps only.');
      log('  If that\'s unexpected, make sure you\'re deploying the right folder;');
      log('  if you need general hosting, contact us about paid plans.\n');
      return { exitCode: 1, command: 'deploy', status: 'not-piezas-app' };
    }

    // CLI-1: deploy ships the build AS-IS (it never builds) — surface the two
    // silent traps: a build older than the source, and an outdated SDK that a
    // fix will never reach without update + rebuild + redeploy. Warn, never block.
    const staleness = detectStaleBuild(projectDir, options);
    if (staleness?.stale) {
      log('');
      log('  ⚠ Your build looks STALE — source files changed after it was built:');
      log(`     changed:   ${relative(projectDir, staleness.newestSourcePath)}  (${new Date(staleness.newestSourceMtimeMs).toLocaleString()})`);
      log(`     built:     ${relative(projectDir, staleness.buildPath)}  (${new Date(staleness.buildMtimeMs).toLocaleString()})`);
      log('     Deploy ships the build output as-is, so those changes will NOT go live.');
      log('     To include them:  npm run build   then deploy again.');
      log('');
    }
    const nudge = await sdkVersionNudge(projectDir, fetchFn);
    if (nudge) log(nudge);

    execSync(`tar -czf ${JSON.stringify(tarball)} -C ${JSON.stringify(staging)} .`);
    const size = stat(tarball).size;
    const limitMB = resolveMaxArtifactMB(env);
    if (size > limitMB * 1024 * 1024) {
      log(`  Artifact is ${(size / 1024 / 1024).toFixed(0)} MB — the limit is ${limitMB} MB per app.`);
      log('  Large media belongs in the Documents service, not the app bundle.');
      log('  (Piezas hosting has its own size limit; the local cap can be raised with PIEZAS_MAX_ARTIFACT_MB.)\n');
      return { exitCode: 1, command: 'deploy', status: 'too-large' };
    }
    log(`  Packaged ${staged.kind} app from ${staged.source} (${(size / 1024 / 1024).toFixed(1)} MB)`);
    if (staged.removed?.length) {
      const envFiles = staged.removed.filter((p) => !p.split('/').includes('.git'));
      if (envFiles.length) log(`  Left out ${envFiles.join(', ')} (local only), it is never uploaded.`);
    }

    const appName = linked.appName;

    // Env: deploy transmits ONLY values explicitly typed as --env KEY=VALUE.
    // The hosted runtime's environment is the cloud store — PIEZAS_API_KEY is
    // provisioned there when the app is created, and everything else is set
    // in the console (Hosting -> Environment). The local .env file is never
    // read: it belongs to local development.
    const sent = collectExplicitEnv(options);
    const sentNames = Object.keys(sent).sort();
    // Not a secret and not a typed setting: the owner's on/off answer above.
    sent.PIEZAS_REPORT_BUTTON = reportChoice.value;
    if (sentNames.length) {
      log(`  Env: sending ${sentNames.join(', ')} (typed via --env)`);
      const localish = sentNames.filter((k) => /localhost|127\.0\.0\.1/.test(String(sent[k])));
      if (localish.length) {
        log(`  Warning: ${localish.join(', ')} point${localish.length === 1 ? 's' : ''} at localhost — the hosted app cannot reach your machine.`);
      }
    }

    // Two-way env verification, client half. The manifest declares what the
    // app NEEDS (deploy.requiredEnv — coding agents keep it updated as they
    // add integrations); each requirement is checked against the CLOUD env
    // (names only, pulled from the platform) plus any typed --env pairs. If
    // anything is missing we refuse to upload, naming it precisely. The
    // server re-verifies the same list post-merge (the second half).
    let required = [];
    try {
      const man = readJsonFile(resolve(projectDir, 'piezas.manifest.json'));
      if (Array.isArray(man?.deploy?.requiredEnv)) {
        required = man.deploy.requiredEnv.filter((k) => typeof k === 'string' && k.trim());
      }
    } catch { /* no manifest -> nothing declared */ }
    // serverKeys was fetched in the pre-packaging preflight above.
    if (required.length) {
      const effective = new Set([...serverKeys, ...Object.keys(sent)]);
      const missing = required.filter((k) => !effective.has(k));
      log(`  Hosted settings check (names only; set at ${appConsoleUrl(linked.appId)} -> Hosting):`);
      for (const k of required) {
        const how = sent[k] !== undefined ? '(sending via --env)' : serverKeys.includes(k) ? '(set in console)' : 'NOT SET';
        log(`    ${effective.has(k) ? '✓' : '✗'} ${k}  ${how}`);
      }
      if (missing.length) {
        // Couldn't read ANY hosted env (no deployment record returned) AND every
        // required var reads missing: the frequent cause is a STALE CLI session,
        // not a genuinely-empty environment. The apps-server returns empty rather
        // than 401 for a token whose control-plane session was revoked or rolled
        // back (see the preflight note above), so the real settings are invisible
        // until you re-auth — `npx piezas env ls` shows the same emptiness. Lead
        // with login; a genuinely first-time-empty deploy loses nothing by trying.
        const likelyStaleSession = !hostedExists && serverKeys.length === 0;
        log('');
        if (likelyStaleSession) {
          log('  Could not read ANY hosted settings for this app. If you already set');
          log('  them, your CLI session is probably stale — refresh it, then retry:');
          log('    npx piezas login        # then: npx piezas deploy');
          log('  (Confirm with `npx piezas env ls` — if it also shows nothing, it is');
          log('  the session, not your settings.)');
          log('');
          log('  If the environment really is empty, set the values:');
        } else {
          log('  Not deploying — the app declares env it would boot without.');
          log('  Set the missing values first (either way works):');
        }
        for (const line of whereToSetLines(linked.appId, missing)) log(line);
        log('  Then deploy again.\n');
        return { exitCode: 1, command: 'deploy', status: 'missing-env', missing, likelyStaleSession, consoleUrl: appConsoleUrl(linked.appId) };
      }
    }

    // A Piezas SERVER app without PIEZAS_API_KEY in its hosted env would boot
    // and then 401 on every backend call — the evidence gate already proved
    // this app calls Piezas, so shipping it keyless ships it broken. HARD
    // GATE: block, but first offer to fix it right here (mint + stage — the
    // same provisioning app creation does). Static apps are exempt (no
    // server-side key), and a typed --env PIEZAS_API_KEY counts.
    if (staged.kind === 'server' && !linked.keyStaged
      && !serverKeys.includes('PIEZAS_API_KEY') && !sent.PIEZAS_API_KEY) {
      log('  This app has no PIEZAS_API_KEY in its hosted environment — it would');
      log('  deploy, boot, and then fail every Piezas call.');
      let fixed = false;
      let mint;
      if (options.interactive && options.promptFn !== null) {
        const promptFn = options.promptFn ?? promptViaTerminal;
        const a = String((await promptFn('  Mint an API key for this app and stage it now? [Y/n] ')) ?? '')
          .trim().toLowerCase();
        if (a === '' || a === 'y' || a === 'yes') {
          mint = await mintAndStageHostedKey(linked, credentials, options, fetchFn);
          fixed = mint.ok;
          if (mint.ok) {
            log('  Key minted and staged in the hosted environment — continuing.');
          } else if (mint.status === 401 || mint.status === 403) {
            log(`  Could not mint the key — your session was rejected (HTTP ${mint.status}).`);
            log('  Run `npx piezas login`, then deploy again.');
          } else {
            log(`  Could not mint/stage the key automatically (${mint.stage} HTTP ${mint.status}).`);
          }
        }
      }
      if (!fixed) {
        log('  Set it first, then deploy again:');
        for (const line of whereToSetLines(linked.appId, ['PIEZAS_API_KEY'])) log(line);
        log('    or, in your own terminal: npx piezas deploy  (offers to create and set the key for you)\n');
        return {
          exitCode: 1, command: 'deploy', status: 'missing-piezas-key',
          mintStatus: mint?.status, mintStage: mint?.stage,
        };
      }
    }

    // The never-rules, checked here on the packaged build before anything is
    // uploaded, the same way the hosting server checks it. An older server
    // without that check still gets this pause. One owner confirmation covers
    // both: the fingerprint is computed the same way on both sides.
    const localFindings = scanArtifactHardNo(staging, staged.kind);
    if (localFindings.length) {
      const fingerprint = hardNoFingerprint(localFindings);
      const confirmed = options.acknowledge || confirmedDeployRisk(projectDir);
      if (confirmed !== fingerprint) {
        return await deployNeedsConfirmation(projectDir, options, {
          fingerprint,
          hardNo: localFindings,
          error: hardNoConfirmMessage(localFindings),
        });
      }
    }

    const form = new FormData();
    form.set('app', appName);
    form.set('appId', linked.appId);
    form.set('kind', staged.kind);
    form.set('env', JSON.stringify(sent));
    // Always sent, `null` included: the platform must be able to tell "this
    // deploy was never tested" from "this client is too old to say".
    form.set('attestation', JSON.stringify(attestation ?? null));
    if (required.length) form.set('requiredEnv', JSON.stringify(required));
    if (typeof options.cmd === 'string' && options.cmd.trim()) form.set('cmd', options.cmd.trim());
    form.set('artifact', new Blob([readFileSync(tarball)]), 'app.tar.gz');
    // The owner's confirmation of exactly the findings they were shown (typed
    // "deploy anyway" in their AI tool, or answered at the terminal prompt).
    const acknowledged = options.acknowledge || confirmedDeployRisk(projectDir);
    if (acknowledged) form.set('acknowledgeHardNo', acknowledged);

    log(`  Uploading to ${base} ...`);
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), options.deployTimeoutMs ?? DEPLOY_TIMEOUT_MS);
    let res;
    try {
      const raw = await netFetch(fetchFn, `${base}/v1/deployments`, {
        method: 'POST',
        headers: { authorization: `Bearer ${credentials.cliToken}` },
        body: form,
        signal: controller.signal,
      });
      let data;
      try { data = await raw.json(); } catch { data = undefined; }
      res = { status: raw.status, data };
    } finally {
      clearTimeout(timer);
    }

    if (res.status === 401) {
      log('  Your session has expired — run `npx piezas login`, then retry.\n');
      return { exitCode: 1, command: 'deploy', status: 'unauthorized' };
    }
    if (res.status === 409 && res.data?.needsConfirmation) {
      return await deployNeedsConfirmation(projectDir, options, res.data);
    }
    if (res.status !== 201) {
      log(`  Deploy failed (HTTP ${res.status}): ${res.data?.error || 'unknown error'}`);
      if (res.data?.logs) {
        log('  --- app output ---');
        console.log(res.data.logs);
      }
      log('');
      return { exitCode: 1, command: 'deploy', status: `http-${res.status}` };
    }

    if (acknowledged) clearPendingDeployRisk(projectDir);
    persistDeploySlug(projectDir, res.data.slug, res.data.url);
    log('');
    log(`  ✓ Live at ${res.data.url}${sandbox ? '  (simulated — nothing was published)' : ''}`);
    // The server's never-rule scan (warn mode): live, but the owner must know.
    for (const f of Array.isArray(res.data.hardNo) ? res.data.hardNo : []) {
      const what = f.rule === 'local-database'
        ? `the app keeps its own local database (${f.detail})`
        : `the Piezas key is visible to every visitor (${f.path})`;
      log(`  ⚠ Piezas check: ${what}. Fix this soon — the platform will start refusing it.`);
    }
    log('  Status any time:  npx piezas deploy --status');
    log('  Logs:             npx piezas deploy --logs\n');
    return { exitCode: 0, command: 'deploy', ...res.data };
  } catch (error) {
    log(`  Deploy failed: ${error?.message || error}\n`);
    return { exitCode: 1, command: 'deploy', status: 'error' };
  } finally {
    try { rmSync(staging, { recursive: true, force: true }); } catch { /* best-effort */ }
    try { unlinkSync(tarball); } catch { /* may not exist */ }
  }
}

// envCmd implements `piezas env ls|set KEY=VALUE|rm KEY` against the HOSTED
// environment (the cloud store the app actually runs with). ls prints names
// only — values are write-only everywhere, terminal included.
// The app's page on the Piezas console: its Hosting card holds the
// environment editor (write-only values), available before the first deploy.
export function appConsoleUrl(appId) {
  return appId ? `${TARGET.console}/apps/${encodeURIComponent(appId)}` : TARGET.console;
}

// whereToSetLines — where the PERSON sets values themselves. Never through an
// AI chat: a chat can be kept for a long time.
export function whereToSetLines(appId, names) {
  return [
    '  Set them yourself (values never go through an AI chat):',
    `    on the app page: ${appConsoleUrl(appId)}  (Hosting -> Environment)`,
    `    or in your own terminal: npx piezas env set ${names.map((k) => `${k}=...`).join(' ')}`,
  ];
}

// --- Report a problem ------------------------------------------------------
// Every app with a server carries a "Report a problem" button (contract v6).
// Reports land in the app's own records (entity problem_reports, status new).
// `piezas reports` lists the new ones; `--save` writes them into
// .piezas/reports/ for the AI to fix together and marks them received, so the
// next run shows only newer ones. It reads the app's own key the way the app
// does locally (PIEZAS_API_KEY, else the project .env) and never prints it.
export const REPORT_ENTITY_SLUG = 'problem_reports';

export function appApiBase(projectDir, env) {
  const fromEnv = typeof env.PIEZAS_API_BASE === 'string' && env.PIEZAS_API_BASE.trim() ? env.PIEZAS_API_BASE.trim() : undefined;
  const manifestBase = readManifestSafe(projectDir)?.apiBaseUrl;
  return (fromEnv || (typeof manifestBase === 'string' && manifestBase) || TARGET_HOSTS[savedTarget(env)].api).replace(/\/+$/, '');
}

export async function reports(options = {}) {
  const env = options.env ?? process.env;
  const projectDir = options.cwd || process.cwd();
  const fetchFn = options.fetchFn ?? fetch;
  const result = (exitCode, status, extra = {}) => ({ exitCode, command: 'reports', status, ...extra });

  if (isSandboxProject(projectDir)) {
    log('  Practice mode has no real app, so there are no problem reports.\n');
    return result(0, 'sandbox', { reports: [] });
  }
  const key = (typeof env.PIEZAS_API_KEY === 'string' && env.PIEZAS_API_KEY.trim()) || readEnvKeyValue(resolve(projectDir, '.env'));
  if (!key) {
    log('  This project has no app key yet, so reports cannot be read. Run `npx piezas init` first.\n');
    return result(1, 'no-key');
  }
  const apiBase = appApiBase(projectDir, env);
  const exchange = await fetchJson(fetchFn, `${adminBaseUrl(apiBase)}/v1/auth/token`, {
    method: 'POST', body: { api_key: key }, timeoutMs: options.httpTimeoutMs,
  });
  const token = exchange.data?.access_token;
  if (exchange.status !== 200 || !token) {
    log(`  Could not sign in with this app's key (HTTP ${exchange.status}).\n`);
    return result(1, `http-${exchange.status}`);
  }
  const entities = `${apiBase}/entities`;
  const http = { token, timeoutMs: options.httpTimeoutMs };
  const schemas = await fetchJson(fetchFn, `${entities}/v1/schemas`, http);
  if (schemas.status !== 200) {
    log(`  Could not read the app's records (HTTP ${schemas.status}).\n`);
    return result(1, `http-${schemas.status}`);
  }
  const list = Array.isArray(schemas.data) ? schemas.data : (schemas.data?.data ?? []);
  const schema = list.find((x) => x?.slug === REPORT_ENTITY_SLUG);
  if (!schema) {
    log('  No problem reports yet.\n');
    return result(0, 'none', { reports: [] });
  }
  const qs = new URLSearchParams({ entity_type_id: schema.id, status: 'new', limit: '100' });
  const records = await fetchJson(fetchFn, `${entities}/v1/records?${qs}`, http);
  if (records.status !== 200) {
    log(`  Could not read the problem reports (HTTP ${records.status}).\n`);
    return result(1, `http-${records.status}`);
  }
  const found = (records.data?.data ?? []).map((r) => ({
    id: r.id,
    message: String(r.data?.message ?? r.title ?? ''),
    page: r.data?.page ?? null,
    browser: r.data?.browser ?? null,
    viewport: r.data?.viewport || null,
    context: (() => { try { return r.data?.context ? JSON.parse(r.data.context) : null; } catch { return null; } })(),
    screenshotId: r.data?.screenshot_document_id || null,
    reportedAt: r.data?.reported_at ?? r.createdAt ?? null,
  }));
  if (!found.length) {
    log('  No new problem reports.\n');
    return result(0, 'none', { reports: [] });
  }

  log(`  ${found.length} new problem report${found.length === 1 ? '' : 's'}:\n`);
  for (const r of found) {
    log(`  - ${r.message.length > 120 ? `${r.message.slice(0, 117)}...` : r.message}${r.screenshotId ? ' (with screenshot)' : ''}`);
    if (r.page) log(`    on ${r.page}`);
  }
  log('');
  if (!options.save) {
    log('  Run `npx piezas reports --save` to collect them into .piezas/reports/ and mark them received.\n');
    return result(0, 'listed', { reports: found });
  }

  const dir = resolve(projectDir, '.piezas', 'reports');
  safeMkdir(dir);
  const saved = [];
  for (const r of found) {
    const name = String(r.id).replace(/[^A-Za-z0-9_-]/g, '_');
    // The screenshot first: it is what the AI should look at before anything.
    let image = null;
    if (r.screenshotId) image = await downloadReportScreenshot(fetchFn, `${apiBase}/documents`, http, r.screenshotId, join(dir, name));
    const lines = [
      `# Problem report ${r.id}`,
      '',
      `- Reported: ${r.reportedAt ?? 'unknown'}`,
      `- Page: ${r.page ?? 'unknown'}`,
      `- Window: ${r.viewport ?? 'unknown'}`,
      `- Browser: ${r.browser ?? 'unknown'}`,
      `- Screenshot: ${image ? basename(image) : r.screenshotId ? 'could not be downloaded' : 'none'}`,
      '',
      '## What they wrote',
      '',
      r.message,
      '',
    ];
    const errors = r.context?.console ?? [];
    const failed = r.context?.network ?? [];
    if (errors.length) {
      lines.push('## Errors and warnings on the page', '');
      for (const e of errors) lines.push(`- ${e.level ?? 'error'}: ${String(e.message ?? '').slice(0, 300)}`);
      lines.push('');
    }
    if (failed.length) {
      lines.push('## Failed requests', '');
      for (const f of failed) lines.push(`- ${f.method ?? 'GET'} ${f.url ?? '?'} -> ${f.status === 0 ? 'no response' : f.status}`);
      lines.push('');
    }
    const file = join(dir, `${name}.md`);
    writeFileSync(file, lines.join('\n'));
    const mark = await fetchJson(fetchFn, `${entities}/v1/records/${encodeURIComponent(r.id)}`, { ...http, method: 'PUT', body: { status: 'received' } });
    saved.push({ ...r, file: relative(projectDir, file), image: image ? relative(projectDir, image) : null, marked: mark.status === 200 });
  }
  log(`  Saved ${saved.length} report${saved.length === 1 ? '' : 's'} to .piezas/reports/.`);
  const unmarked = saved.filter((r) => !r.marked).length;
  if (unmarked) log(`  ${unmarked} could not be marked received and will show again next time.`);
  log('');
  return result(0, 'saved', { reports: saved });
}

// Downloads a report's screenshot from the app's Documents next to its .md.
// Returns the file path, or null if it could not be fetched.
export async function downloadReportScreenshot(fetchFn, documentsBase, http, documentId, pathWithoutExtension) {
  try {
    const link = await fetchJson(fetchFn, `${documentsBase}/v1/documents/${encodeURIComponent(documentId)}/download-url`, http);
    const url = link.data?.downloadUrl;
    if (link.status !== 200 || !url) return null;
    const response = await netFetch(fetchFn, url);
    if (!response.ok) return null;
    const type = String(response.headers?.get?.('content-type') ?? '');
    const extension = type.includes('png') ? 'png' : type.includes('webp') ? 'webp' : 'jpg';
    const file = `${pathWithoutExtension}.${extension}`;
    writeFileSync(file, Buffer.from(await response.arrayBuffer()));
    return file;
  } catch {
    return null;
  }
}

// `piezas report-button on|off`: a shortcut that saves the default answer for
// the next deploy's question. The deploy itself sets the hosted switch.
export function reportButton(options = {}) {
  const projectDir = options.cwd || process.cwd();
  const manifestPath = resolve(projectDir, 'piezas.manifest.json');
  const state = options.state;
  let manifest;
  try { manifest = readJsonFile(manifestPath); } catch { manifest = null; }
  if (!manifest) {
    log('  No piezas.manifest.json here. Run `npx piezas init` first.\n');
    return { exitCode: 1, command: 'report-button', status: 'no-manifest' };
  }
  if (state !== 'on' && state !== 'off') {
    const current = manifest.reportButton === false ? 'off' : 'on';
    log(`  The Report a problem button is ${current}. Change it with \`npx piezas report-button on\` or \`off\`.\n`);
    return { exitCode: state === undefined ? 0 : 2, command: 'report-button', status: current };
  }
  if (state === 'off') manifest.reportButton = false;
  else delete manifest.reportButton;
  writeFileSync(manifestPath, `${JSON.stringify(manifest, null, 2)}\n`);
  log(`  Saved: the Report a problem button defaults to ${state} at your next deploy (you are still asked each time).\n`);
  return { exitCode: 0, command: 'report-button', status: state };
}

export async function envCmd(options = {}) {
  const env = options.env ?? process.env;
  const projectDir = options.cwd || process.cwd();
  const fetchFn = platformFetch(projectDir, options);
  const base = appsBaseUrl(options, env);

  if (isSandboxProject(projectDir)) log(`  ${SANDBOX_NOTE}\n`);

  const credentials = platformCredentials(projectDir, env);
  if (!credentials) {
    log(`  ${signInNeededLine(env, options)}\n`);
    return { exitCode: 1, command: 'env', status: 'not-logged-in' };
  }
  const httpOptions = { token: credentials.cliToken, timeoutMs: options.httpTimeoutMs };
  const slug = deploySlugFor(projectDir, options);
  const appId = (() => {
    try { return readJsonFile(resolve(projectDir, 'piezas.manifest.json')).deploy?.appId ?? null; } catch { return null; }
  })();
  const idQS = appId ? `?appId=${encodeURIComponent(appId)}` : '';

  const action = options.action;
  if (action === 'check') {
    // Names only, never values: what the app declares it needs
    // (deploy.requiredEnv in piezas.manifest.json, the same list deploy and
    // the hosting server check) against what is set in the hosted environment.
    let required = [];
    try {
      const man = readJsonFile(resolve(projectDir, 'piezas.manifest.json'));
      if (Array.isArray(man?.deploy?.requiredEnv)) required = man.deploy.requiredEnv.filter((k) => typeof k === 'string' && k.trim());
    } catch { /* no manifest -> nothing declared */ }
    const res = await fetchJson(fetchFn, `${base}/v1/deployments/${slug}${idQS}`, httpOptions);
    if (res.status !== 200 && res.status !== 404) {
      log(`  Could not read the hosted environment (HTTP ${res.status}).\n`);
      return { exitCode: 1, command: 'env', status: `http-${res.status}` };
    }
    const set = res.status === 200 ? (res.data.envKeys ?? []) : [];
    const missing = required.filter((k) => !set.includes(k));
    if (!missing.length) {
      log(required.length ? `  All ${required.length} required settings are set.\n` : '  This app declares no required settings.\n');
      return { exitCode: 0, command: 'env', status: 'ok', required, missing };
    }
    log(`  Missing settings: ${missing.join(', ')}`);
    for (const line of whereToSetLines(appId, missing)) log(line);
    log('');
    return { exitCode: 1, command: 'env', status: 'missing', required, missing, consoleUrl: appConsoleUrl(appId) };
  }

  if (action === 'ls' || action === undefined) {
    const res = await fetchJson(fetchFn, `${base}/v1/deployments/${slug}${idQS}`, httpOptions);
    if (res.status === 404) {
      log('  No hosted environment yet — set a variable (here or in the console) to create it.');
      log('  Expected settings here? Your CLI session may be stale — run `npx piezas login` and retry.\n');
      return { exitCode: 0, command: 'env', status: 'empty', keys: [] };
    }
    if (res.status !== 200) {
      log(`  Could not read the hosted environment (HTTP ${res.status}).\n`);
      return { exitCode: 1, command: 'env', status: `http-${res.status}` };
    }
    const keys = res.data.envKeys ?? [];
    log(`  Hosted env for ${res.data.slug} (${res.data.status}) — names only, values are write-only:`);
    for (const k of keys) log(`    ${k}`);
    if (!keys.length) log('    (none set)');
    log('');
    return { exitCode: 0, command: 'env', status: 'ok', keys };
  }

  if (action === 'set' || action === 'rm') {
    const body = { set: {}, unset: [] };
    const refusedEmpty = [];
    for (const arg of options.args ?? []) {
      if (action === 'set') {
        const m = /^([A-Za-z_][A-Za-z0-9_]*)=([\s\S]*)$/.exec(String(arg));
        if (!m) {
          log(`  Skipping "${arg}" — expected KEY=VALUE.`);
          continue;
        }
        // An empty value is almost always a shell-expansion bug (KEY=$TYPO
        // expands to KEY=) — and it "succeeds" silently, leaving the app to
        // fail in ways that take an evening to trace back here. Refuse unless
        // the emptiness is explicit.
        if (m[2] === '' && !options.allowEmpty) {
          log(`  Refusing to set ${m[1]} to an EMPTY value — usually an unset shell variable.`);
          log(`    Meant it? Re-run with --allow-empty, or remove the variable with: env rm ${m[1]}`);
          refusedEmpty.push(m[1]);
          continue;
        }
        body.set[m[1]] = m[2];
      } else {
        body.unset.push(String(arg));
      }
    }
    // Atomic: one empty value aborts the WHOLE call. Applying the good keys
    // while a script's `&& deploy` sails past the refused one would recreate
    // exactly the silent breakage this guard exists to stop.
    if (refusedEmpty.length) {
      log(`  Nothing was applied — fix the empty value${refusedEmpty.length > 1 ? 's' : ''} and re-run.\n`);
      return { exitCode: 2, command: 'env', status: 'empty-value', refusedEmpty };
    }
    if (!Object.keys(body.set).length && !body.unset.length) {
      log(`  Nothing to ${action === 'set' ? 'set — pass KEY=VALUE' : 'remove — pass the variable name'}.\n`);
      return { exitCode: 2, command: 'env', status: 'usage' };
    }
    const res = await fetchJson(fetchFn, `${base}/v1/deployments/${slug}/env${idQS}`, {
      ...httpOptions, method: 'PATCH', body,
    });
    if (res.status !== 200) {
      log(`  Could not update the hosted environment (HTTP ${res.status}): ${res.data?.error || ''}\n`);
      return { exitCode: 1, command: 'env', status: `http-${res.status}` };
    }
    const what = [...Object.keys(body.set), ...body.unset].join(', ');
    log(`  Hosted env updated (${what}).${res.data.status === 'not deployed' ? ' Staged — in place before first deploy.' : ' App restarted.'}\n`);
    return { exitCode: 0, command: 'env', status: 'ok', keys: res.data.envKeys ?? [] };
  }

  log(`  Unknown env action "${action}" — use ls, check, set KEY=VALUE, or rm KEY.\n`);
  return { exitCode: 2, command: 'env', status: 'usage' };
}

// --- End piezas deploy -----------------------------------------------------

export function detectPackageManager(projectDir) {
  if (existsSync(resolve(projectDir, 'pnpm-lock.yaml'))) return 'pnpm';
  if (existsSync(resolve(projectDir, 'yarn.lock'))) return 'yarn';
  if (existsSync(resolve(projectDir, 'bun.lockb'))) return 'bun';
  return 'npm';
}

// hasSdkDependency reports whether package.json already declares @piezas/sdk
// (e.g. a `file:` tarball pin for testing a local build). Init must not clobber
// such a pin by re-adding the published package from the registry.
export function hasSdkDependency(projectDir) {
  const pkgJsonPath = resolve(projectDir, 'package.json');
  if (!existsSync(pkgJsonPath)) return false;
  try {
    const pkg = JSON.parse(readFileSync(pkgJsonPath, 'utf8'));
    return Boolean(
      pkg?.dependencies?.['@piezas/sdk'] || pkg?.devDependencies?.['@piezas/sdk'],
    );
  } catch {
    return false;
  }
}

